import express, { Express } from 'express';
import { errorHandlerMiddleware } from '../http/middleware/ErrorHandlerMiddleware';
import { UuidIdGenerator } from '../identity/UuidIdGenerator';
import { InMemoryProjectRepository } from '../persistence/InMemoryProjectRepository';
import { InMemoryTaskRepository } from '../persistence/InMemoryTaskRepository';
import { InMemoryUserRepository } from '../persistence/InMemoryUserRepository';
import { Dependencies } from './Dependencies';
import { createProjectRoutes } from './ProjectModule';
import { createTaskRoutes } from './TaskModule';
import { createUserRoutes } from './UserModule';

export function createApp(): Express {
  const deps: Dependencies = {
    users: new InMemoryUserRepository(),
    projects: new InMemoryProjectRepository(),
    tasks: new InMemoryTaskRepository(),
    ids: new UuidIdGenerator(),
  };

  const app = express();
  app.use(express.json());
  app.use(createUserRoutes(deps));
  app.use(createProjectRoutes(deps));
  app.use(createTaskRoutes(deps));
  app.use(errorHandlerMiddleware);
  return app;
}

