import { Router } from 'express';
import { CreateProjectUseCase } from '../../application/use-cases/CreateProjectUseCase';
import { CreateTaskUseCase } from '../../application/use-cases/CreateTaskUseCase';
import { ListProjectTasksUseCase } from '../../application/use-cases/ListProjectTasksUseCase';
import { ProjectController } from '../http/controllers/ProjectController';
import { Dependencies } from './Dependencies';

export function createProjectRoutes(deps: Dependencies): Router {
  return new ProjectController(
    new CreateProjectUseCase(deps.projects, deps.ids),
    new CreateTaskUseCase(deps.projects, deps.tasks, deps.ids),
    new ListProjectTasksUseCase(deps.projects, deps.tasks),
  ).routes();
}

